    // [FIX] Splash disembunyikan setelah video logo (logo_reveal.mp4) BENAR-
    // BENAR SELESAI diputar (event "ended"), bukan waktu tetap - supaya video
    // tidak terpotong. Tetap ada batas waktu maksimal sebagai jaga-jaga (mis.
    // kalau videonya gagal diputar/diblokir browser) supaya splash tidak
    // nyangkut selamanya.
    (function() {
      function hidePwaSplash() {
        var el = document.getElementById('pwaSplash');
        if (!el) return;
        el.style.opacity = '0';
        el.style.visibility = 'hidden';
        setTimeout(function() { if (el.parentNode) el.parentNode.removeChild(el); }, 550);
      }
      var hidden = false;
      function hideOnce() { if (hidden) return; hidden = true; hidePwaSplash(); }
      var vid = document.querySelector('#pwaSplash video');
      if (vid) {
        vid.addEventListener('ended', hideOnce);
        vid.addEventListener('error', function() { setTimeout(hideOnce, 2200); }); // video gagal dimuat - jangan tunggu lama, langsung fallback ke gambar statis (lihat onerror di elemen video) & tutup splash lebih cepat
      }
      setTimeout(hideOnce, 9000); // jaga-jaga mutlak - sedikit lebih lama dari durasi video, supaya splash tidak pernah nyangkut selamanya
    })();

    // [NEW] Cek Transaksi Publik — kalau URL-nya ?cek=1 (atau apa saja setelah "cek="),
    // langsung tampilkan halaman publik ini SEBELUM alur login normal di bawah dicek sama
    // sekali. window._publicMode dibaca lagi nanti di bagian bootstrap login (dekat akhir
    // file) supaya showMainApp()/showBioLockScreen() TIDAK dipanggil untuk mode ini.
    window._publicMode = new URLSearchParams(location.search).has('cek');
    if (window._publicMode) {
      document.addEventListener('DOMContentLoaded', function() {
        var p = document.getElementById('publicCekPage');
        if (p) p.classList.remove('hidden');
        var lp = document.getElementById('loginPage'); if (lp) lp.style.display = 'none';
      });
    }
  

    // ==================== KONSTANTA DAN GLOBAL ====================
    const DEFAULT_GAS_URL = 'https://script.google.com/macros/s/AKfycbwdPgjTCISgyyaT8DSfPs14jUNCb8rSjzX7W8MoVHq_pbkdoNAMD-3lgBBJI-L57NWkSQ/exec';
    let GAS_URL = localStorage.getItem('tirtaGasUrl') || DEFAULT_GAS_URL;
    const EMBEDDED_LOGO = "data:image/png;base64,"; // [UPDATED] Logo Tirta Kencana (logo dolphin baru), tertanam sebagai base64 supaya tidak bergantung ke hosting eksternal dan aman dari isu CORS di html2canvas
    const EMBEDDED_QRIS = "https://www.image2url.com/r2/default/images/1781920179544-5e92dd0f-d0fa-482c-afc2-88259a5d3000.jpg"; // [UPDATED] QRIS asli, tertanam agar langsung muncul tanpa upload manual
    function getGasUrl() { return localStorage.getItem('tirtaGasUrl') || DEFAULT_GAS_URL; }
    // [SECURITY FIX] Token sesi dari login server - dikirim di SETIAP panggilan
    // gasCall/gasUploadFoto supaya backend bisa menolak request yang tidak login.
    let sessionToken = null;

    // [FIX] gasCall dengan retry dan timeout diperpanjang
    // ══════════════════════════════════════════════════════════════
    // [NEW] gasCall sekarang coba POST dulu (fetch), baru fallback ke GET/JSONP kalau
    // POST gagal karena alasan apa pun (CORS, jaringan, dll). Alasannya: GET/JSONP
    // (cara lama, satu-satunya sebelum ini) mengirim SEMUA data lewat URL, yang ada
    // batas panjangnya (~45KB) - daftar produk/pelanggan yang sudah banyak, apalagi
    // kalau ada foto, gampang kena batas itu dan gagal terkirim tanpa pesan jelas.
    // POST (lewat body request, bukan URL) TIDAK punya batas seperti itu.
    // Fallback otomatis ke GET/JSONP menjaga supaya tidak ada regresi - kalau di
    // deployment GAS tertentu POST-nya bermasalah (jarang, tapi mungkin), app tetap
    // jalan seperti sebelumnya lewat GET.
    // ══════════════════════════════════════════════════════════════
    // Fungsi yang memang butuh waktu lama (AI, kirim email): batas waktu lebih panjang dan TANPA jalur cadangan GET,
    // supaya server tidak diminta mengerjakan hal yang sama dua kali (boros jatah AI / email ganda).
    const _GAS_LONG = { aiTanya: 75000, kirimLaporanEmail: 60000, kirimNotifTes: 45000, selfTest: 60000, backupNow: 60000 };
    async function gasCall(fn, args = [], retry = 1) {
      if (_GAS_LONG[fn]) return await _gasCallPost(fn, args, _GAS_LONG[fn]);
      try {
        return await _gasCallPost(fn, args);
      } catch (postErr) {
        console.warn('gasCall: POST gagal (' + postErr.message + '), fallback ke GET/JSONP...');
        return await _gasCallGet(fn, args, retry);
      }
    }
    function _gasCallPost(fn, args, ms) {
      return new Promise((resolve, reject) => {
        const controller = (typeof AbortController !== 'undefined') ? new AbortController() : null;
        const timer = setTimeout(() => { if (controller) controller.abort(); }, ms || 20000);
        // [NOTE] Content-Type 'text/plain' sengaja dipakai (walau isinya JSON) supaya
        // browser TIDAK mengirim CORS preflight (OPTIONS) - Apps Script web app tidak
        // punya handler doOptions, jadi preflight akan gagal & memblokir request kalau
        // pakai 'application/json'. Apps Script tetap bisa JSON.parse() isi body-nya
        // apa pun Content-Type yang tertulis di header, jadi ini aman.
        fetch(getGasUrl(), {
          method: 'POST',
          headers: { 'Content-Type': 'text/plain;charset=utf-8' },
          body: JSON.stringify({ fn, args, token: sessionToken || '' }),
          signal: controller ? controller.signal : undefined
        }).then(res => {
          clearTimeout(timer);
          if (!res.ok) throw new Error('HTTP ' + res.status);
          return res.json();
        }).then(r => {
          if (r && r.ok) { resolve(r.data); return; }
          const errMsg = (r && r.error) || 'GAS error: tidak ada respon valid';
          if (fn !== 'login' && fn !== 'getPublicTrxDetail' && (errMsg.indexOf('SESSION_INVALID') >= 0 || errMsg.indexOf('SESSION_EXPIRED') >= 0)) {
            forceReLogin_('Sesi login sudah habis. Silakan login lagi.');
          }
          reject(new Error(errMsg));
        }).catch(e => { clearTimeout(timer); reject(ms && (e.name === 'AbortError' || /abort/i.test(String(e.message))) ? new Error('Server masih memproses terlalu lama (lebih dari ' + Math.round(ms/1000) + ' detik). Coba lagi sebentar lagi.') : e); });
      });
    }
    async function _gasCallGet(fn, args = [], retry = 1) {
      return new Promise((resolve, reject) => {
        const cb = 'cb_' + Date.now() + '_' + Math.floor(Math.random() * 1e6);
        const argsStr = JSON.stringify(args);
        // [FIX] Jalur GET/JSONP ini (sekarang cuma dipakai sbg fallback) tetap ada batas
        // praktis panjang URL (~45KB) - kalau POST di atas berhasil, jalur ini tidak
        // pernah dipakai utk payload besar sama sekali. Pengecekan ini jaga-jaga murni
        // utk skenario fallback saja.
        if (argsStr.length > 45000) {
          reject(new Error(`Data terlalu besar untuk dikirim lewat GET fallback (${Math.round(argsStr.length/1000)}KB, batas aman ~45KB), dan POST juga gagal. Kemungkinan ada foto/gambar ikut tersimpan di data - cek dan kecilkan ukuran foto, atau kurangi jumlah data yang dikirim sekaligus.`));
          return;
        }
        const url = getGasUrl() + '?fn=' + encodeURIComponent(fn) + '&args=' + encodeURIComponent(argsStr) + '&token=' + encodeURIComponent(sessionToken || '') + '&callback=' + cb + '&t=' + Date.now();
        const script = document.createElement('script');
        let done = false;
        const timer = setTimeout(() => {
          if (done) return;
          done = true;
          script.src = '';
          if (script.parentNode) script.parentNode.removeChild(script);
          delete window[cb];
          if (retry > 0) {
            console.warn(`GAS timeout, retry ${retry}...`);
            _gasCallGet(fn, args, retry - 1).then(resolve).catch(reject);
          } else {
            reject(new Error('GAS timeout atau tidak merespon. Cek URL dan pastikan sudah deploy sebagai Web App dengan akses "Anyone".'));
          }
        }, 20000); // timeout 20 detik
        window[cb] = function(r) {
          if (done) return;
          done = true;
          clearTimeout(timer);
          if (script.parentNode) script.parentNode.removeChild(script);
          delete window[cb];
          if (r && r.ok) resolve(r.data);
          else {
            const errMsg = (r && r.error) || 'GAS error: tidak ada respon valid';
            if (fn !== 'login' && fn !== 'getPublicTrxDetail' && (errMsg.indexOf('SESSION_INVALID') >= 0 || errMsg.indexOf('SESSION_EXPIRED') >= 0)) {
              forceReLogin_('Sesi login sudah habis. Silakan login lagi.');
            }
            reject(new Error(errMsg));
          }
        };
        script.async = true;
        script.src = url;
        // [NEW] Deteksi gagal load lebih cepat (URL salah/tidak bisa diakses/network error) tanpa menunggu 20 detik
        script.onerror = () => {
          if (done) return;
          done = true;
          clearTimeout(timer);
          if (script.parentNode) script.parentNode.removeChild(script);
          delete window[cb];
          if (retry > 0) {
            console.warn(`GAS gagal dimuat (kemungkinan URL salah/tidak bisa diakses), retry ${retry}...`);
            _gasCallGet(fn, args, retry - 1).then(resolve).catch(reject);
          } else {
            reject(new Error('GAS gagal dimuat. Kemungkinan URL Web App salah, deployment tidak aktif, atau tidak ada koneksi internet. Cek URL: ' + getGasUrl()));
          }
        };
        document.head.appendChild(script);
      });
    }

    // ══════════════════════════════════════════════════════════════
    // [NEW] SYNC QUEUE - antrian sync persisten
    // ------------------------------------------------------------------
    // Masalah yang diperbaiki: sebelumnya SETIAP fitur (simpan transaksi, setoran,
    // input barang, pengaturan, dst) punya cara sendiri-sendiri buat "coba kirim ke
    // server, kalau gagal ya sudah, cuma console.warn atau toast sebentar". Kalau
    // toast-nya kelewat/koneksi lagi jelek pas itu juga, perubahan itu HILANG dari
    // radar - tidak ada catatan bahwa itu masih "berhutang" ke server, dan tidak ada
    // yang otomatis coba lagi nanti. Itu akar dari beberapa masalah "kok datanya
    // beda di HP vs Sheets" yang muncul sepanjang sesi ini.
    //
    // Solusinya: SATU antrian pusat, tersimpan di localStorage (jadi tidak hilang
    // walau app ditutup/HP restart). Setiap perubahan data penting masuk ke sini
    // (bukan panggil gasCall langsung). Antrian ini terus dicoba dikirim: langsung
    // saat ditambahkan, ulang tiap 25 detik selama masih ada isinya, DAN begitu HP
    // balik online setelah offline. Berhasil -> dicoret dari antrian. Gagal -> tetap
    // di antrian, dicoba lagi nanti, TIDAK PERNAH diam-diam hilang.
    //
    // Aman dari dobel: retry di level ini ada di ATAS backend yang sudah dibikin
    // idempotent (saveTrx/saveInputBarang cek ID dulu sebelum simpan) - jadi walau
    // sama-sama retry, tidak akan pernah menghasilkan data ganda di Sheets.
    // ══════════════════════════════════════════════════════════════
    const SYNC_QUEUE_KEY = 'tirtaSyncQueue';
    let _syncQueue = [];
    let _syncProcessing = false;

    function _loadSyncQueue() {
      try { _syncQueue = JSON.parse(localStorage.getItem(SYNC_QUEUE_KEY) || '[]'); } catch(e) { _syncQueue = []; }
    }
    function _saveSyncQueueState() {
      localStorage.setItem(SYNC_QUEUE_KEY, JSON.stringify(_syncQueue));
      updateSyncBadge();
    }
    // Dipanggil dari semua tempat yang tadinya langsung gasCall(...) untuk simpan
    // data. label = teks singkat yang ditampilkan ke user kalau item ini gagal
    // berkali-kali (misal 'Transaksi TRX-123').
    function enqueueSync(fn, args, label) {
      const item = { qid: 'q_' + Date.now() + '_' + Math.floor(Math.random()*1e6), fn: fn, args: args, addedAt: Date.now(), attempts: 0, lastError: null, label: label || fn };
      _syncQueue.push(item);
      _saveSyncQueueState();
      processSyncQueue();
      return item.qid;
    }
    async function processSyncQueue() {
      if (_syncProcessing) return; // cegah 2 proses jalan bersamaan (dobel kirim)
      if (typeof navigator !== 'undefined' && navigator.onLine === false) { updateSyncBadge(); return; }
      if (_syncQueue.length === 0) { updateSyncBadge(); return; }
      _syncProcessing = true;
      const snapshot = _syncQueue.slice();
      const MAX_AUTO_ATTEMPTS = 15; // [NEW] setelah gagal 15x otomatis (±6 menit), berhenti coba sendiri -
                                     // tetap ada di antrian/badge, tapi nunggu diklik manual (mencegah retry
                                     // tanpa henti selamanya kalau errornya memang bukan soal koneksi)
      for (const item of snapshot) {
        if (!_syncQueue.find(q => q.qid === item.qid)) continue; // sudah dihapus di iterasi lain
        if (item.attempts >= MAX_AUTO_ATTEMPTS) continue; // sudah lewat batas, skip auto-retry, nunggu manual
        try {
          await gasCall(item.fn, item.args, 0); // retry di sini cukup 1 lapis (di processSyncQueue sendiri), gasCall tidak perlu retry internal lagi
          _syncQueue = _syncQueue.filter(q => q.qid !== item.qid);
          _saveSyncQueueState();
        } catch(e) {
          if (/TERKUNCI|Akses ditolak/i.test(e.message || '')) { // ditolak permanen oleh server: jangan diulang terus
            _syncQueue = _syncQueue.filter(q => q.qid !== item.qid); _saveSyncQueueState();
            try { Swal.fire({ toast:true, position:'top-end', showConfirmButton:false, timer:4000, icon:'warning', title:'Ditolak server: ' + String(e.message).replace(/\s*\(.*\)$/, '').substring(0, 120) }); } catch(x) {}
            continue;
          }
          const idx = _syncQueue.findIndex(q => q.qid === item.qid);
          if (idx >= 0) { _syncQueue[idx].attempts++; _syncQueue[idx].lastError = e.message; }
          _saveSyncQueueState();
          console.warn('Sync queue gagal (akan dicoba lagi otomatis):', item.fn, item.label, e.message);
        }
      }
      _syncProcessing = false;
      updateSyncBadge();
    }
    const SYNC_STALE_MS = 3 * 3600 * 1000; // data tertahan > 3 jam dianggap perlu perhatian
    function _syncOldestAge() { return _syncQueue.length ? Date.now() - Math.min(..._syncQueue.map(q => q.addedAt || Date.now())) : 0; }
    function _syncIsStale() { return _syncQueue.length > 0 && _syncOldestAge() > SYNC_STALE_MS; }
    function _ageTxt(ms) {
      const m = Math.max(0, Math.round(ms / 60000));
      if (m < 1) return 'baru saja';
      if (m < 60) return m + ' menit';
      const h = Math.floor(m / 60);
      if (h < 24) return h + ' jam' + (m % 60 ? ' ' + (m % 60) + ' mnt' : '');
      return Math.floor(h / 24) + ' hari ' + (h % 24) + ' jam';
    }
    function updateSyncBadge() {
      const n = _syncQueue.length;
      const stuck = _syncQueue.some(q => q.attempts >= 15) || _syncIsStale();
      const offline = (typeof navigator !== 'undefined' && navigator.onLine === false);
      const badge = document.getElementById('syncQueueBadge');
      if (badge) { badge.style.display = n > 0 ? 'inline-flex' : 'none'; badge.textContent = n > 99 ? '99+' : n; badge.style.background = stuck ? '#ef4444' : '#f59e0b'; }
      const statusEl = document.getElementById('syncStatus');
      if (statusEl) {
        if (offline) { statusEl.textContent = '📴 Offline' + (n ? ' · ' + n + ' antre' : ''); statusEl.style.color = '#f59e0b'; }
        else if (n === 0) { statusEl.textContent = '✓ Tersinkron'; statusEl.style.color = ''; }
        else if (stuck) { statusEl.textContent = '⚠ ' + n + ' tertahan'; statusEl.style.color = '#ef4444'; }
        else { statusEl.textContent = '⏳ ' + n + ' belum sync'; statusEl.style.color = '#f59e0b'; }
      }
    }
    // Detail antrian yang gagal - dipanggil dari klik badge, supaya user bisa lihat
    // persis apa yang mengganjal & alasannya, bukan cuma angka doang.
    function showSyncQueueDetail() {
      if (_syncQueue.length === 0) {
        Swal.fire({ icon: 'success', title: 'Semua Tersinkron', text: 'Tidak ada data yang mengantre ke Google Sheets saat ini.' });
        return;
      }
      const isAdmin = currentUser && currentUser.role === 'admin';
      const offline = (typeof navigator !== 'undefined' && navigator.onLine === false);
      const stale = _syncIsStale();
      const items = _syncQueue.slice().sort((a, b) => (a.addedAt || 0) - (b.addedAt || 0)).map(q => {
        const age = Date.now() - (q.addedAt || Date.now());
        const old = age > SYNC_STALE_MS || q.attempts >= 15;
        return `<div class="sq-it ${old ? 'old' : ''}">
          <div class="sq-main"><div class="sq-l">${esc(q.label || q.fn)}</div>
            <div class="sq-s">Menunggu ${esc(_ageTxt(age))} · ${q.attempts}x dicoba${q.attempts >= 15 ? ' · <b>berhenti otomatis</b>' : ''}</div>
            ${q.lastError ? `<div class="sq-e">${esc(String(q.lastError).substring(0, 140))}</div>` : ''}</div>
          <div class="sq-b"><button type="button" class="sq-btn" onclick="_sqRetry('${q.qid}')">Coba</button>${isAdmin ? `<button type="button" class="sq-btn del" onclick="_sqDiscard('${q.qid}')">Buang</button>` : ''}</div>
        </div>`;
      }).join('');
      const warn = offline ? '📴 Perangkat sedang offline. Data akan dikirim otomatis saat internet kembali.'
        : stale ? '⚠️ Ada data yang tertahan lebih dari 3 jam. Pastikan internet stabil, lalu tekan “Coba Kirim Semua”. Jika tetap gagal, tekan “Salin Laporan” dan kirim ke admin.'
        : 'Otomatis dicoba lagi tiap ±25 detik & saat internet nyambung. Data AMAN tersimpan di HP ini walau belum terkirim.';
      Swal.fire({
        title: `${_syncQueue.length} Data Belum Terkirim`,
        html: `<div class="sq"><div class="sq-warn ${stale || offline ? 'bad' : ''}">${warn}</div>
          <div class="sq-sum"><span>Tertua: <b>${esc(_ageTxt(_syncOldestAge()))}</b></span><span>Jumlah: <b>${_syncQueue.length}</b></span></div>
          <div class="sq-list">${items}</div></div>`,
        width: 460, confirmButtonText: 'Coba Kirim Semua', showDenyButton: true, denyButtonText: 'Salin Laporan', showCancelButton: true, cancelButtonText: 'Tutup'
      }).then(r => {
        if (r.isConfirmed) { _syncQueue.forEach(q => { q.attempts = 0; }); _saveSyncQueueState(); processSyncQueue(); }
        else if (r.isDenied) {
          const txt = 'Antrian sync ' + (settings.namaToko || 'Tirta Kencana') + ' — ' + new Date().toLocaleString('id-ID') + '\n' + _syncQueue.map(q => `- ${q.label || q.fn} | ${_ageTxt(Date.now() - (q.addedAt || Date.now()))} | ${q.attempts}x | ${q.lastError || '-'}`).join('\n');
          try { navigator.clipboard.writeText(txt); Swal.fire({ toast: true, position: 'top-end', showConfirmButton: false, timer: 2000, icon: 'success', title: 'Laporan disalin' }); } catch (e) { window.open('https://wa.me/?text=' + encodeURIComponent(txt), '_blank'); }
        }
      });
    }
    function _sqRetry(qid) {
      const q = _syncQueue.find(x => x.qid === qid); if (!q) return;
      q.attempts = 0; _saveSyncQueueState(); processSyncQueue();
      setTimeout(() => showSyncQueueDetail(), 1800);
    }
    function _sqDiscard(qid) {
      const q = _syncQueue.find(x => x.qid === qid); if (!q) return;
      Swal.fire({ icon: 'warning', title: 'Buang dari antrian?', html: `<b>${esc(q.label || q.fn)}</b><br>Data ini <b>tidak akan terkirim</b> ke Google Sheets. Gunakan hanya jika data sudah ada di Sheet atau memang salah.`, showCancelButton: true, confirmButtonText: 'Ya, buang', cancelButtonText: 'Batal', confirmButtonColor: '#DC2626' })
        .then(r => { if (r.isConfirmed) { _syncQueue = _syncQueue.filter(x => x.qid !== qid); _saveSyncQueueState(); showSyncQueueDetail(); } else showSyncQueueDetail(); });
    }
    if (typeof window !== 'undefined') {
      window.addEventListener('online', () => { console.log('Koneksi kembali online, proses antrian sync...'); processSyncQueue(); });
      setInterval(() => { if (_syncQueue.length > 0) processSyncQueue(); }, 25000);
      window.addEventListener('offline', () => updateSyncBadge());
      let _lastStaleToast = 0;
      setInterval(() => {
        updateSyncBadge();
        if (_syncIsStale() && Date.now() - _lastStaleToast > 2 * 3600 * 1000) {
          _lastStaleToast = Date.now();
          try { Swal.fire({ toast: true, position: 'top', showConfirmButton: false, timer: 7000, timerProgressBar: true, icon: 'warning', title: _syncQueue.length + ' data tertahan > 3 jam. Ketuk status sinkron di atas.' }); } catch (e) {}
        }
      }, 600000);
    }
    // [NEW] Dashboard Kesehatan Sync - supaya kalau ada masalah sync (sering
    // terjadi sepanjang pengembangan app ini: rollover stok, item transaksi
    // hilang, dsb), admin bisa cek sendiri kondisinya tanpa harus lapor dulu:
    // kapan terakhir berhasil sync, ada berapa yang masih mengantre, dan
    // jumlah data yang tersimpan lokal di device ini per jenis data.
    function showSyncHealthDashboard() {
      const lastOK = parseInt(localStorage.getItem('tirtaLastSyncOK')) || 0;
      const lastErrRaw = localStorage.getItem('tirtaLastSyncError');
      let lastErr = null; try { lastErr = lastErrRaw ? JSON.parse(lastErrRaw) : null; } catch(e) {}
      const fmtRelative = (ts) => {
        if (!ts) return 'Belum pernah';
        const diffMin = Math.round((Date.now() - ts) / 60000);
        if (diffMin < 1) return 'Baru saja';
        if (diffMin < 60) return diffMin + ' menit lalu';
        const diffJam = Math.round(diffMin / 60);
        if (diffJam < 24) return diffJam + ' jam lalu';
        return Math.round(diffJam / 24) + ' hari lalu';
      };
      const queueOk = _syncQueue.length === 0;
      const dataRows = [
        { label: 'Transaksi', count: allTrxList.length },
        { label: 'Produk', count: products.length },
        { label: 'Pelanggan', count: allCustomers.length },
        { label: 'Input Barang', count: stockInHistory.length },
        { label: 'Setoran', count: setoranHistory.length },
      ];
      const html = `<div style="text-align:left">
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:14px">
          <div style="background:${queueOk?'#EEF9F2':'#FEF3E2'};border-radius:12px;padding:10px 12px">
            <div style="font-size:0.68rem;color:#5a7a90">Status Antrian</div>
            <div style="font-weight:800;font-size:1rem;color:${queueOk?'#16A34A':'#D97706'}">${queueOk ? '✓ Tersinkron' : _syncQueue.length + ' menunggu'}</div>
          </div>
          <div style="background:${lastErr?'#FEECEC':'#F4F8FB'};border-radius:12px;padding:10px 12px">
            <div style="font-size:0.68rem;color:#5a7a90">Sync Berhasil Terakhir</div>
            <div style="font-weight:800;font-size:0.9rem;color:${lastErr?'#DC2626':'#0D2B3E'}">${esc(fmtRelative(lastOK))}</div>
          </div>
        </div>
        ${lastErr ? `<div style="background:#FEECEC;border-radius:10px;padding:10px 12px;margin-bottom:12px;font-size:0.72rem;color:#DC2626"><b>⚠️ Percobaan sync terakhir gagal</b> (${esc(fmtRelative(lastErr.time))}): ${esc(lastErr.message||'-')}</div>` : ''}
        <div style="font-weight:700;font-size:0.8rem;color:#0D2B3E;margin-bottom:6px">Jumlah Data Tersimpan di Device Ini</div>
        <div style="border:1px solid #EEF4F9;border-radius:10px;overflow:hidden;margin-bottom:14px">
          ${dataRows.map(r => `<div style="display:flex;justify-content:space-between;padding:7px 12px;border-bottom:1px solid #F1F5F9;font-size:0.78rem"><span style="color:#5a7a90">${esc(r.label)}</span><span style="font-weight:700;color:#0D2B3E;font-family:monospace">${r.count}</span></div>`).join('')}
        </div>
        <p style="font-size:0.68rem;color:#94A3B8">Antrian otomatis dicoba lagi tiap ±25 detik & saat internet nyambung. Data yang belum sync AMAN tersimpan di HP ini.</p>
      </div>`;
      Swal.fire({
        title: '🩺 Kesehatan Sync', html, width: '460px', background: '#F4F8FB',
        showConfirmButton: true, confirmButtonText: 'Tutup',
        showDenyButton: !queueOk, denyButtonText: 'Lihat Detail Antrian',
        showCancelButton: true, cancelButtonText: '🔄 Sync Sekarang',
        customClass: { popup: 'dash-status-popup' }
      }).then(r => {
        if (r.isDenied) showSyncQueueDetail();
        else if (r.dismiss === Swal.DismissReason.cancel) syncFromGAS();
      });
    }
    // berlaku / tidak valid). Paksa kembali ke halaman login dengan pesan jelas,
    // supaya tidak muncul error generik berulang-ulang di seluruh menu.
    let _reloginTriggered = false;
    function forceReLogin_(message) {
      if (_reloginTriggered) return;
      _reloginTriggered = true;
      stopAutoSync();
      localStorage.removeItem('tirtaUser');
      currentUser = null;
      sessionToken = null;
      document.getElementById('mainApp').classList.add('hidden');
      document.getElementById('loginPage').classList.remove('hidden');
      if (typeof Swal !== 'undefined') Swal.fire('Sesi Habis', message, 'info');
    }

    // [NEW] Khusus untuk kirim foto (base64 besar). gasCall (JSONP/GET) tidak dipakai di sini karena
    // data foto dimasukkan ke query string URL, dan base64 foto (ratusan KB - 1.5MB) jauh melebihi batas
    // panjang URL yang diizinkan browser/server (hanya beberapa KB) -> <script> gagal load -> muncul
    // error "GAS gagal dimuat". Fungsi ini mengirim lewat fetch POST (body request, bukan URL) supaya
    // tidak kena limit tersebut. Memakai Content-Type text/plain agar tidak memicu CORS preflight
    // (teknik standar untuk POST ke GAS Web App). Endpoint dan parameter (fn/args) sama seperti gasCall,
    // tinggal pastikan GAS punya fungsi doPost yang meneruskan ke router yang sama dengan doGet.
    async function gasUploadFoto(fn, args = []) {
      const resp = await fetch(getGasUrl(), {
        method: 'POST',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ fn, args, token: sessionToken || '' })
      });
      if (!resp.ok) throw new Error('GAS gagal merespon (HTTP ' + resp.status + ').');
      const r = await resp.json();
      if (r && r.ok) return r.data;
      const errMsg = (r && r.error) || 'GAS error: tidak ada respon valid';
      if (errMsg.indexOf('SESSION_INVALID') >= 0 || errMsg.indexOf('SESSION_EXPIRED') >= 0) {
        forceReLogin_('Sesi login sudah habis. Silakan login lagi.');
      }
      throw new Error(errMsg);
    }


    let currentUser = null, currentPage = 'dashboard';

    // ============================================================
    // [NEW] LOGIN BIOMETRIK (Sidik Jari / Wajah)
    // Ini lapisan KUNCI LOKAL di atas sesi yang sudah tersimpan (token 30 hari
    // dari server), BUKAN pengganti verifikasi username/password ke server.
    // - Kredensial WebAuthn didaftarkan ke platform authenticator HP (sidik
    //   jari/Face ID bawaan), disimpan oleh OS/browser; cuma ID kredensialnya
    //   yang disimpan di localStorage device ini.
    // - Saat app dibuka lagi & sesi tersimpan masih ada, sebelum masuk ke
    //   dashboard, app minta verifikasi sidik jari/wajah dulu (dicek oleh
    //   OS/browser sendiri). Kalau berhasil, sesi yang SUDAH ADA dipakai
    //   masuk — tidak ada password yang dikirim ulang ke server.
    // - Kalau HP tidak punya sidik jari/Face ID, atau browser tidak
    //   mendukung WebAuthn, fitur ini otomatis disembunyikan (tidak
    //   memaksa/mengganggu alur login biasa).
    // ============================================================
    function openWhatsAppApp() {
      // [FIX v3] Percobaan "buka WhatsApp tanpa tujuan chat apa pun" (generik) tidak
      // reliable di Android - itu bukan bug, tapi keterbatasan platform: WhatsApp
      // (dan kebanyakan app lain) cuma mendaftarkan dirinya ke Android untuk dibuka
      // lewat link yang menuju KONTEN SPESIFIK (chat ke nomor tertentu), bukan link
      // generik "buka app tanpa tujuan". Sesuai pilihan user: sekarang diarahkan ke
      // chat dengan nomor WA toko. 'wa.me' adalah domain resmi WhatsApp yang sudah
      // terverifikasi (Android/iOS App Link) - kalau app WhatsApp terpasang, link ini
      // akan langsung membuka APP-nya (bukan browser/WhatsApp Web), tanpa perlu
      // akal-akalan intent:// atau custom scheme lagi.
      // [NEW] Di Android: buka app WhatsApp langsung lewat intent (tanpa tab browser baru),
      // sehingga kalau WhatsApp sudah ada di panel split screen / app pair, cukup naik ke depan.
      // Kalau app tidak terbuka (bukan Android / WhatsApp belum terpasang), fallback ke wa.me.
      const fallback = () => window.open('https://wa.me/6288211058000', '_blank');
      if (/Android/i.test(navigator.userAgent)) {
        let left = false;
        const onHide = () => { if (document.hidden) left = true; };
        document.addEventListener('visibilitychange', onHide);
        window.location.href = 'intent:#Intent;action=android.intent.action.MAIN;category=android.intent.category.LAUNCHER;package=com.whatsapp;end';
        setTimeout(() => { document.removeEventListener('visibilitychange', onHide); if (!left && !document.hidden) fallback(); }, 1500);
      } else fallback();
    }

    function isBiometricSupported() {
      return !!(window.PublicKeyCredential && navigator.credentials && navigator.credentials.create);
    }
    function _randBytes(len) { const a = new Uint8Array(len); crypto.getRandomValues(a); return a; }
    async function enableBiometricLock() {
      if (!isBiometricSupported()) { Swal.fire('Tidak Didukung', 'Perangkat/browser ini tidak mendukung login biometrik.', 'error'); return false; }
      try {
        if (PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable) {
          const available = await PublicKeyCredential.isUserVerifyingPlatformAuthenticatorAvailable();
          if (!available) { Swal.fire('Tidak Tersedia', 'Belum ada sidik jari/Face ID yang terdaftar di HP ini. Setel dulu lewat Pengaturan HP kamu.', 'warning'); return false; }
        }
        const cred = await navigator.credentials.create({
          publicKey: {
            challenge: _randBytes(32),
            rp: { name: 'Tirta Kencana POS' },
            user: { id: _randBytes(16), name: (currentUser && currentUser.name) || 'user', displayName: (currentUser && currentUser.name) || 'User' },
            pubKeyCredParams: [{ type: 'public-key', alg: -7 }, { type: 'public-key', alg: -257 }],
            authenticatorSelection: { authenticatorAttachment: 'platform', userVerification: 'required', residentKey: 'preferred' },
            timeout: 60000
          }
        });
        if (!cred) throw new Error('Pendaftaran dibatalkan');
        const credIdB64 = btoa(String.fromCharCode.apply(null, new Uint8Array(cred.rawId)));
        localStorage.setItem('tirtaBioCredId', credIdB64);
        localStorage.setItem('tirtaBioEnabled', '1');
        Swal.fire({ toast: true, position: 'top-end', showConfirmButton: false, timer: 2000, icon: 'success', title: 'Login biometrik diaktifkan!' });
        return true;
      } catch (e) {
        Swal.fire('Gagal', 'Tidak bisa mengaktifkan login biometrik: ' + e.message, 'error');
        return false;
      }
    }
    function disableBiometricLock() {
      localStorage.removeItem('tirtaBioCredId');
      localStorage.removeItem('tirtaBioEnabled');
      Swal.fire({ toast: true, position: 'top-end', showConfirmButton: false, timer: 1500, icon: 'success', title: 'Login biometrik dinonaktifkan' });
      renderBioSettingUI();
    }
    async function promptBiometricUnlock() {
      const credIdB64 = localStorage.getItem('tirtaBioCredId');
      if (!credIdB64) return false;
      try {
        const raw = Uint8Array.from(atob(credIdB64), c => c.charCodeAt(0));
        const assertion = await navigator.credentials.get({
          publicKey: { challenge: _randBytes(32), allowCredentials: [{ id: raw, type: 'public-key' }], userVerification: 'required', timeout: 60000 }
        });
        return !!assertion;
      } catch (e) {
        // [FIX] Sebelumnya error apapun didiamkan total (cuma return false) -
        // kalau kredensial yang tersimpan sudah tidak valid lagi di perangkat
        // (mis. sidik jari di-reset, ganti HP, atau browser/OS update), user
        // akan terjebak selamanya di "Verifikasi gagal/dibatalkan" tanpa tahu
        // sebabnya & tanpa jalan keluar selain "Gunakan Password". Sekarang
        // errornya dicatat (buat didiagnosis) & kalau memang kredensialnya yang
        // bermasalah, ditawarkan langsung untuk daftar ulang.
        console.warn('Biometric unlock gagal:', e.name, e.message);
        window._lastBioError = e;
        return false;
      }
    }
    function showBioLockScreen() {
      const el = document.getElementById('bioLockScreen');
      if (!el) { showMainApp(); return; } // fallback aman kalau markup lock screen belum ter-upload
      el.classList.remove('hidden');
      document.getElementById('loginPage').classList.add('hidden');
      document.getElementById('mainApp').classList.add('hidden');
      attemptBioUnlock();
    }
    async function attemptBioUnlock() {
      const statusEl = document.getElementById('bioLockStatus');
      if (statusEl) statusEl.textContent = 'Menunggu sidik jari/wajah...';
      const ok = await promptBiometricUnlock();
      if (ok) {
        document.getElementById('bioLockScreen').classList.add('hidden');
        showMainApp();
      } else if (statusEl) {
        statusEl.textContent = 'Verifikasi gagal/dibatalkan. Coba lagi, atau masuk pakai password.';
      }
    }
    function bioLockUsePassword() {
      document.getElementById('bioLockScreen').classList.add('hidden');
      doLogout(); // balik ke form login manual (username/password) seperti biasa
    }
    function renderBioSettingUI() {
      const statusEl = document.getElementById('bioSettingStatus');
      const btnEl = document.getElementById('bioSettingBtn');
      if (!statusEl || !btnEl) return;
      if (!isBiometricSupported()) {
        statusEl.textContent = 'Perangkat/browser ini tidak mendukung login biometrik.';
        btnEl.textContent = 'Tidak Didukung'; btnEl.disabled = true; return;
      }
      const enabled = localStorage.getItem('tirtaBioEnabled') === '1';
      statusEl.textContent = enabled ? 'Aktif di perangkat ini — app akan minta sidik jari/wajah tiap dibuka.' : 'Nonaktif — app langsung masuk seperti biasa tanpa diminta sidik jari/wajah.';
      btnEl.disabled = false;
      btnEl.innerHTML = enabled ? '<i class="fas fa-lock-open"></i> Nonaktifkan Login Biometrik' : '<i class="fas fa-fingerprint"></i> Aktifkan Login Biometrik';
    }
    async function toggleBiometricSetting() {
      const enabled = localStorage.getItem('tirtaBioEnabled') === '1';
      if (enabled) { disableBiometricLock(); } else { await enableBiometricLock(); renderBioSettingUI(); }
    }

    // ========== [NEW] KUNCI POLA (PATTERN LOCK) ==========
    // Catatan: login biometrik di atas (WebAuthn) SUDAH otomatis mencakup Face ID -
    // di HP yang Face ID-nya aktif (mis. iPhone), enableBiometricLock() di atas akan
    // memunculkan prompt Face ID dengan sendirinya (browser yang memilih sensor mana
    // yang dipakai, bukan sesuatu yang bisa/perlu dipisah lewat kode). Makanya label
    // di pengaturan sudah ditulis "Sidik Jari / Face ID".
    // Pattern Lock ini fitur BARU & terpisah - pola 3x3 titik yang digambar dengan
    // jari (seperti kunci pola Android), sebagai alternatif buat device yang tidak
    // punya sensor biometrik, atau buat yang lebih suka pola.
    async function _sha256Hex(str) {
      const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(str));
      return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
    }
    function _patternDotCoord(i) { return { x: 50 + (i % 3) * 100, y: 50 + Math.floor(i / 3) * 100 }; }
    function _patternHitTest(x, y) {
      for (let i = 0; i < 9; i++) { const c = _patternDotCoord(i); if (Math.hypot(x - c.x, y - c.y) <= 32) return i; }
      return -1;
    }
    function _patternGridSvgHtml() {
      let dots = '';
      for (let i = 0; i < 9; i++) {
        const c = _patternDotCoord(i);
        dots += `<circle class="pattern-dot-outer" data-i="${i}" cx="${c.x}" cy="${c.y}" r="28" fill="transparent" stroke="rgba(0,168,232,0.35)" stroke-width="2"></circle>
                 <circle class="pattern-dot-inner" data-i="${i}" cx="${c.x}" cy="${c.y}" r="9" fill="rgba(0,168,232,0.55)"></circle>`;
      }
      return `<svg id="patternSvg" viewBox="0 0 300 300" style="width:250px;height:250px;touch-action:none;user-select:none">
        <g id="patternLines"></g>
        <line id="patternDragLine" x1="0" y1="0" x2="0" y2="0" stroke="#00D1FF" stroke-width="4" stroke-linecap="round" style="display:none"></line>
        ${dots}
      </svg>`;
    }
    // Memasang interaksi gambar-pola (drag jari/mouse) ke satu elemen SVG grid.
    // onFinish(sequence) dipanggil setiap kali user selesai menggambar (angkat jari),
    // sequence = array indeks titik (0-8) yang dilewati, urut sesuai gambar.
    function _wirePatternDrag(svg, onFinish) {
      const linesG = svg.querySelector('#patternLines');
      const dragLine = svg.querySelector('#patternDragLine');
      let sequence = [], dragging = false;
      function svgPoint(e) {
        const r = svg.getBoundingClientRect();
        return { x: (e.clientX - r.left) / r.width * 300, y: (e.clientY - r.top) / r.height * 300 };
      }
      function markDot(i) {
        const inner = svg.querySelector(`.pattern-dot-inner[data-i="${i}"]`);
        const outer = svg.querySelector(`.pattern-dot-outer[data-i="${i}"]`);
        if (inner) { inner.setAttribute('fill', '#00D1FF'); inner.setAttribute('r', '11'); }
        if (outer) outer.setAttribute('stroke', '#00D1FF');
      }
      function addSegment(i1, i2) {
        const c1 = _patternDotCoord(i1), c2 = _patternDotCoord(i2);
        const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
        line.setAttribute('x1', c1.x); line.setAttribute('y1', c1.y);
        line.setAttribute('x2', c2.x); line.setAttribute('y2', c2.y);
        line.setAttribute('stroke', '#00D1FF'); line.setAttribute('stroke-width', '4'); line.setAttribute('stroke-linecap', 'round');
        linesG.appendChild(line);
      }
      function reset() {
        sequence = []; linesG.innerHTML = ''; dragLine.style.display = 'none';
        svg.querySelectorAll('.pattern-dot-inner').forEach(el => { el.setAttribute('fill', 'rgba(0,168,232,0.55)'); el.setAttribute('r', '9'); });
        svg.querySelectorAll('.pattern-dot-outer').forEach(el => el.setAttribute('stroke', 'rgba(0,168,232,0.35)'));
      }
      function onDown(e) {
        const p = svgPoint(e); const hit = _patternHitTest(p.x, p.y);
        if (hit < 0) return;
        reset(); dragging = true; sequence.push(hit); markDot(hit); dragLine.style.display = 'block';
        if (svg.setPointerCapture) { try { svg.setPointerCapture(e.pointerId); } catch (err) {} }
      }
      function onMove(e) {
        if (!dragging) return;
        const p = svgPoint(e);
        const last = _patternDotCoord(sequence[sequence.length - 1]);
        dragLine.setAttribute('x1', last.x); dragLine.setAttribute('y1', last.y);
        dragLine.setAttribute('x2', p.x); dragLine.setAttribute('y2', p.y);
        const hit = _patternHitTest(p.x, p.y);
        if (hit >= 0 && !sequence.includes(hit)) { addSegment(sequence[sequence.length - 1], hit); sequence.push(hit); markDot(hit); }
      }
      function onUp() {
        if (!dragging) return;
        dragging = false; dragLine.style.display = 'none';
        const finished = sequence.slice();
        reset();
        onFinish(finished);
      }
      svg.addEventListener('pointerdown', onDown);
      svg.addEventListener('pointermove', onMove);
      svg.addEventListener('pointerup', onUp);
      svg.addEventListener('pointerleave', onUp);
    }
    // Modal sekali-gambar (dipakai saat SETUP pola baru) - resolve(sequence) kalau
    // berhasil (>=4 titik), resolve(null) kalau dibatalkan.
    function _promptDrawPatternOnce(title) {
      return new Promise((resolve) => {
        const modal = document.createElement('div');
        modal.style.cssText = 'position:fixed;inset:0;z-index:9999;background:rgba(0,10,25,0.92);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;padding:20px;';
        modal.innerHTML = `<div style="color:#fff;font-weight:700;font-size:1rem;text-align:center;max-width:280px">${esc(title)}</div>
          <div id="pgw"></div>
          <div id="patternHintOnce" style="color:#9fc1e6;font-size:0.8rem">Hubungkan minimal 4 titik</div>
          <button type="button" class="btn btn-outline" id="patternCancelOnce" style="color:#fff;border-color:rgba(255,255,255,0.3)">Batal</button>`;
        document.body.appendChild(modal);
        modal.querySelector('#pgw').innerHTML = _patternGridSvgHtml();
        const svg = modal.querySelector('#patternSvg');
        _wirePatternDrag(svg, (seq) => {
          if (seq.length < 4) { modal.querySelector('#patternHintOnce').textContent = 'Terlalu pendek, minimal 4 titik - coba lagi'; return; }
          modal.remove(); resolve(seq);
        });
        modal.querySelector('#patternCancelOnce').onclick = () => { modal.remove(); resolve(null); };
      });
    }
    function isPatternLockEnabled() { return localStorage.getItem('tirtaPatternEnabled') === '1'; }
    async function enablePatternLock() {
      const p1 = await _promptDrawPatternOnce('Gambar pola kunci baru');
      if (!p1) return false;
      const p2 = await _promptDrawPatternOnce('Gambar ulang pola yang sama untuk konfirmasi');
      if (!p2) return false;
      if (p1.join('-') !== p2.join('-')) { Swal.fire('Tidak Cocok', 'Pola konfirmasi tidak sama dengan yang pertama. Coba lagi.', 'error'); return false; }
      localStorage.setItem('tirtaPatternHash', await _sha256Hex(p1.join('-')));
      localStorage.setItem('tirtaPatternEnabled', '1');
      Swal.fire({ toast: true, position: 'top-end', showConfirmButton: false, timer: 2000, icon: 'success', title: 'Kunci pola diaktifkan!' });
      return true;
    }
    function disablePatternLock() {
      localStorage.removeItem('tirtaPatternHash');
      localStorage.removeItem('tirtaPatternEnabled');
      Swal.fire({ toast: true, position: 'top-end', showConfirmButton: false, timer: 1500, icon: 'success', title: 'Kunci pola dinonaktifkan' });
      renderPatternSettingUI();
    }
    async function togglePatternSetting() {
      if (isPatternLockEnabled()) { disablePatternLock(); } else { await enablePatternLock(); renderPatternSettingUI(); }
    }
    function renderPatternSettingUI() {
      const statusEl = document.getElementById('patternSettingStatus');
      const btnEl = document.getElementById('patternSettingBtn');
      if (!statusEl || !btnEl) return;
      const enabled = isPatternLockEnabled();
      statusEl.textContent = enabled ? 'Aktif di perangkat ini — app akan minta gambar pola tiap dibuka.' : 'Nonaktif — app langsung masuk seperti biasa tanpa diminta pola.';
      btnEl.innerHTML = enabled ? '<i class="fas fa-lock-open"></i> Nonaktifkan Kunci Pola' : '<i class="fas fa-draw-polygon"></i> Aktifkan Kunci Pola';
    }
    // Dipanggil sekali dari halaman Pengaturan (admin/sales/driver) setelah HTML-nya
    // dirender, supaya kedua tombol (biometrik & pola) langsung terisi status yang benar.
    function initKeamananSectionUI() {
      renderBioSettingUI(); renderPatternSettingUI();
      const sel = document.getElementById('autoLockSelect');
      if (sel) sel.value = String(getAutoLockMinutes());
    }

    // Lock-screen pola (dipanggil saat app dibuka & kunci pola aktif) - beda dari
    // modal setup di atas: ini LANGSUNG cek kecocokan hash & LOOPING kalau salah
    // (tidak menutup diri sendiri sampai benar atau user pilih "Gunakan Password").
    // [NEW] Proteksi percobaan gagal - sebelumnya pola bisa dicoba BERKALI-KALI
    // TANPA BATAS kalau salah terus (beda dengan biometrik yang dibatasi sistem
    // OS). Sekarang setiap 5x salah berturut-turut, ada jeda yang makin lama
    // (30d -> 60d -> 120d -> ... maks 5 menit) sebelum bisa coba lagi. Disimpan
    // di localStorage (bukan variabel biasa) supaya tidak bisa di-reset cuma
    // dengan menutup-buka app lagi.
    const PATTERN_FAIL_KEY = 'tirtaPatternFailCount';
    const PATTERN_LOCK_UNTIL_KEY = 'tirtaPatternLockUntil';
    function _getPatternFailCount() { return parseInt(localStorage.getItem(PATTERN_FAIL_KEY)) || 0; }
    function _getPatternLockUntil() { return parseInt(localStorage.getItem(PATTERN_LOCK_UNTIL_KEY)) || 0; }
    function _registerPatternFail() {
      const count = _getPatternFailCount() + 1;
      localStorage.setItem(PATTERN_FAIL_KEY, String(count));
      if (count % 5 === 0) {
        const stage = Math.min(count / 5, 5); // maks di kelipatan ke-5 (5 menit)
        const lockSeconds = Math.min(30 * Math.pow(2, stage - 1), 300);
        localStorage.setItem(PATTERN_LOCK_UNTIL_KEY, String(Date.now() + lockSeconds * 1000));
      }
    }
    function _resetPatternFail() { localStorage.removeItem(PATTERN_FAIL_KEY); localStorage.removeItem(PATTERN_LOCK_UNTIL_KEY); }
    async function showPatternLockScreen() {
      document.getElementById('loginPage').classList.add('hidden');
      document.getElementById('mainApp').classList.add('hidden');
      const hash = localStorage.getItem('tirtaPatternHash');
      if (!hash) { showMainApp(); return; }
      const modal = document.createElement('div');
      modal.id = 'patternLockModal';
      modal.style.cssText = 'position:fixed;inset:0;z-index:9999;background:linear-gradient(160deg,#010d1f,#00509E);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px;padding:20px;';
      modal.innerHTML = `
        <div style="width:60px;height:60px;border-radius:50%;background:rgba(255,255,255,0.12);display:flex;align-items:center;justify-content:center;margin-bottom:4px"><i class="fas fa-draw-polygon" style="font-size:1.6rem;color:#00D1FF"></i></div>
        <div style="color:#fff;font-weight:700;font-size:1.05rem">Gambar Pola untuk Membuka</div>
        <div id="pgw2"></div>
        <div id="patternLockHint" style="color:#9fc1e6;font-size:0.8rem;min-height:1.2em">Hubungkan titik-titik sesuai pola Anda</div>
        <button type="button" class="btn btn-outline" id="patternUsePasswordBtn" style="color:#fff;border-color:rgba(255,255,255,0.35)"><i class="fas fa-key"></i> Gunakan Password</button>`;
      document.body.appendChild(modal);
      modal.querySelector('#pgw2').innerHTML = _patternGridSvgHtml();
      const svg = modal.querySelector('#patternSvg');
      const hintEl = modal.querySelector('#patternLockHint');
      modal.querySelector('#patternUsePasswordBtn').onclick = () => { modal.remove(); doLogout(); };
      // [NEW] Kalau masih dalam masa jeda (lockout) dari percobaan gagal
      // sebelumnya, tampilkan hitung mundur & matikan grid-nya dulu.
      function checkLockoutAndMaybeWire() {
        const lockUntil = _getPatternLockUntil();
        const remaining = lockUntil - Date.now();
        if (remaining > 0) {
          svg.style.pointerEvents = 'none';
          svg.style.opacity = '0.35';
          const detik = Math.ceil(remaining / 1000);
          hintEl.style.color = '#FF8A80';
          hintEl.textContent = `Terlalu banyak percobaan salah. Coba lagi dalam ${detik} detik.`;
          setTimeout(checkLockoutAndMaybeWire, 1000);
          return;
        }
        svg.style.pointerEvents = 'auto';
        svg.style.opacity = '1';
        hintEl.style.color = '#9fc1e6';
        hintEl.textContent = 'Hubungkan titik-titik sesuai pola Anda';
        _wirePatternDrag(svg, async (seq) => {
          if (seq.length < 4) return; // ketuk-lepas tidak sengaja, abaikan diam-diam
          if (_getPatternLockUntil() > Date.now()) return; // jaga-jaga kalau sempat digambar pas jeda baru mulai
          const drawnHash = await _sha256Hex(seq.join('-'));
          if (drawnHash === hash) { _resetPatternFail(); modal.remove(); showMainApp(); }
          else {
            _registerPatternFail();
            if (_getPatternLockUntil() > Date.now()) { checkLockoutAndMaybeWire(); return; }
            hintEl.textContent = 'Pola salah, coba lagi'; hintEl.style.color = '#FF8A80';
            setTimeout(() => { hintEl.style.color = '#9fc1e6'; hintEl.textContent = 'Hubungkan titik-titik sesuai pola Anda'; }, 1500);
          }
        });
      }
      checkLockoutAndMaybeWire();
    }

