    function _ensureQrisDataUrl(url) { // [FIX] konversi url QRIS remote menjadi data URL sebelum dirender ke canvas
      return new Promise((resolve) => {
        if (!url || url.indexOf('data:') === 0) return resolve(url);
        if (_qrisDataCache && _qrisDataCache.src === url) return resolve(_qrisDataCache.data);
        // [BUGFIX] Sebelumnya kalau fetch gagal (mis. hosting gambar QRIS-nya - image2url.com -
        // ternyata tidak mengizinkan CORS), fallback-nya adalah resolve(url) -> balik ke URL
        // remote APA ADANYA. Itu artinya "perbaikan"-nya diam-diam TIDAK terjadi sama sekali:
        // struk tetap dirender pakai <img> lintas-domain yang sama, yang di dalam <canvas>
        // (html2canvas) akan gagal digambar (browser menolak baca piksel gambar lintas-domain
        // tanpa header CORS yang benar) - hasilnya kotak QRIS kosong/putih pas di-download,
        // padahal di preview (elemen HTML biasa, bukan canvas) gambarnya tetap kelihatan normal.
        // Sekarang: kalau gagal, resolve(null) - sinyal jelas "gagal", supaya pemanggil bisa
        // memutuskan utk MELEWATKAN kotak QRIS sama sekali drpd menampilkan kotak kosong.
        fetch(url, { mode: 'cors' }).then(r => r.blob()).then(blob => {
          const reader = new FileReader();
          reader.onload = () => { _qrisDataCache = { src: url, data: reader.result }; resolve(reader.result); };
          reader.onerror = () => resolve(null);
          reader.readAsDataURL(blob);
        }).catch(() => resolve(null));
      });
    }
